class Ticket:
    def __init__(self, code):
        self.code = code

    def show(self):
        print('Ticket: %s' % self.code)

t = Ticket('A17')
t.show()

class PartyAnimal:
    def __init__(self, nam):
        self.name = nam
        self.x = 0

    def party(self):
        self.x = self.x + 1
        print(self.name, 'party', self.x)


class CricketFan(PartyAnimal):
    points = 0

    def six(self):
        self.points = self.points + 6
        self.party()
        print(self.name, 'points', self.points)


j = CricketFan('Jim')
j.six()

class Team:
    def __init__(self, nam):
        self.name = nam
        self.players = list()

    def add_player(self, player):
        self.players.append(player)

    def describe(self):
        print('team: %s' % self.name)
        print('players: %d' % len(self.players))


class Coach(Team):
    def lead(self):
        print('Coach of %s' % self.name)


red = Team('red')
red.add_player('ana')
red.add_player('bo')
red.describe()

blue = Coach('blue')
blue.add_player('cy')
blue.describe()
blue.lead()
